CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE suppliers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, name text NOT NULL, country text, payment_terms text, moq integer NOT NULL DEFAULT 1, active boolean DEFAULT true);
CREATE TABLE products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sku text UNIQUE NOT NULL, name text NOT NULL, category text, unit_cost numeric(12,2) NOT NULL, selling_price numeric(12,2) NOT NULL, supplier_id uuid REFERENCES suppliers(id), launch_date date, active boolean DEFAULT true);
CREATE TABLE supplier_metrics (id bigserial PRIMARY KEY, supplier_id uuid REFERENCES suppliers(id), measured_on date NOT NULL, quoted_lead_days integer, actual_lead_days integer, on_time boolean, defect_rate numeric(8,4) DEFAULT 0);
CREATE TABLE inventory (product_id uuid PRIMARY KEY REFERENCES products(id), on_hand integer NOT NULL DEFAULT 0, allocated integer NOT NULL DEFAULT 0, in_transit integer NOT NULL DEFAULT 0, warehouse text NOT NULL DEFAULT 'Main', updated_at timestamptz DEFAULT now());
CREATE TABLE sales_daily (id bigserial PRIMARY KEY, product_id uuid REFERENCES products(id), sales_date date NOT NULL, channel text NOT NULL, units integer NOT NULL, revenue numeric(12,2), UNIQUE(product_id,sales_date,channel));
CREATE TABLE purchase_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), po_number text UNIQUE NOT NULL, supplier_id uuid REFERENCES suppliers(id), status text NOT NULL CHECK(status IN ('draft','approved','sent','partial','received','cancelled')), order_date date, expected_date date, total_value numeric(14,2) DEFAULT 0, created_at timestamptz DEFAULT now());
CREATE TABLE purchase_order_lines (id bigserial PRIMARY KEY, purchase_order_id uuid REFERENCES purchase_orders(id) ON DELETE CASCADE, product_id uuid REFERENCES products(id), quantity integer NOT NULL, unit_cost numeric(12,2) NOT NULL, received_quantity integer DEFAULT 0);
CREATE TABLE shipments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), purchase_order_id uuid REFERENCES purchase_orders(id), carrier text, tracking_number text, origin text, destination text, eta date, status text, last_event text, updated_at timestamptz DEFAULT now());
CREATE TABLE knowledge_docs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, body text NOT NULL, source text, tags text[], search_vector tsvector GENERATED ALWAYS AS (to_tsvector('english',coalesce(title,'')||' '||coalesce(body,''))) STORED, created_at timestamptz DEFAULT now());
CREATE INDEX knowledge_search_idx ON knowledge_docs USING gin(search_vector);
CREATE TABLE conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text NOT NULL, started_at timestamptz DEFAULT now());
CREATE TABLE memories (id bigserial PRIMARY KEY, conversation_id uuid REFERENCES conversations(id), user_id text NOT NULL, kind text NOT NULL, content jsonb NOT NULL, importance numeric(4,3) DEFAULT .5, created_at timestamptz DEFAULT now());
CREATE TABLE recommendations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid REFERENCES products(id), type text NOT NULL, priority text NOT NULL, rationale jsonb NOT NULL, recommended_quantity integer, status text DEFAULT 'open', created_at timestamptz DEFAULT now());
CREATE TABLE action_drafts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), action_type text NOT NULL, payload jsonb NOT NULL, status text DEFAULT 'awaiting_approval', created_by text, created_at timestamptz DEFAULT now());
CREATE TABLE evaluation_runs (id bigserial PRIMARY KEY, metric text NOT NULL, value numeric(12,4) NOT NULL, dimensions jsonb DEFAULT '{}', measured_at timestamptz DEFAULT now());
